SELECT
 (SELECT COUNT(DISTINCT START_DATE) FROM DATALAKE.MRR.MNG_LOG_STORED_PROCEDURES_EXECUTION WHERE SP_NAME = 'SP_LOAD_EVENTS' AND START_DATE BETWEEN '2026-10-26' AND CURRENT_DATE()) AS loader_success_days,
 DATEDIFF(day, '2026-10-26', CURRENT_DATE()) + 1 AS days_expected,
 (SELECT LISTAGG(STATE || ' ' || SCHEDULED_TIME::date::string, ', ') FROM SNOWFLAKE.ACCOUNT_USAGE.TASK_HISTORY WHERE NAME = 'LAODING_PLAYFAB_LOGS' AND SCHEDULED_TIME >= '2026-10-26' AND STATE NOT IN ('SUCCEEDED', 'SCHEDULED')) AS loader_task_problems,
 (SELECT LISTAGG(md5(PROCEDURE_DEFINITION), ',') FROM SNOWFLAKE.ACCOUNT_USAGE.PROCEDURES WHERE PROCEDURE_CATALOG = 'DATALAKE' AND PROCEDURE_SCHEMA = 'PUBLIC' AND PROCEDURE_NAME = 'INVALID_APPLY_AUTOMATIONS' AND DELETED IS NULL) AS routine_md5,
 (SELECT COUNT(*) FROM DATALAKE.MRR.INVALID_EVENTS) AS set_aside_now,
 (SELECT LISTAGG(TABLE_SCHEMA || '.' || TABLE_NAME || ' retention_days=' || RETENTION_TIME, '; ') FROM DATALAKE.INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME LIKE '%\\_BAK\\_AN1415%' ESCAPE '\\') AS backups_and_restore_window
